<script lang="ts">import { onMount } from 'svelte';import { api } from '$lib/api';let status=$state<any>(null),error=$state(''),updated=$state('');async function refresh(){try{status=await api('status');updated=new Date().toLocaleTimeString();error='';}catch(e){error=e instanceof Error?e.message:'Status unavailable.';}}onMount(()=>{void refresh();const timer=setInterval(refresh,60000);return()=>clearInterval(timer);});</script>
<svelte:head><title>Operating status — Voynich@home</title></svelte:head>
<div class="page narrow"><p class="eyebrow">Operations and release readiness</p><h1>Know what is running.</h1><p class="lede">A quiet queue is a valid state. When a campaign finishes, we stop assigning work until a new campaign or declared continuation is ready.</p>{#if error}<p class="error" role="alert">{error}</p>{/if}
<section class="panel"><h2>{status?.assignments_enabled?'Work assignments are open.':'No work is currently available.'}</h2><p>{status?.reason??'Checking the coordinator…'}</p><p class="small muted">Deployment: {status?.stage??'unknown'} · Last checked: {updated||'not yet'}</p><button class="secondary" onclick={refresh}>Refresh status</button></section>
<section class="panel"><h2>Work queue</h2>{#if status?.queue?.length}<table><thead><tr><th>State</th><th>Work units</th></tr></thead><tbody>{#each status.queue as q}<tr><td>{q.state}</td><td>{q.count}</td></tr>{/each}</tbody></table>{:else}<p class="muted">No work units have been published.</p>{/if}</section>
<section class="panel"><h2>Release status</h2><p>The platform is under development. Local queue checks have passed; hosted recovery, browser resource behavior, account integration, backup restoration, and release rollback must pass before a public release is declared ready.</p><a href="https://github.com/javidmardanov/VoynichAtHome/blob/codex/public-release/docs/RELEASE-STATUS.md">Read the evidence for each release gate ↗</a></section>
<p class="small muted">The initial operating target is $10 per month. The coordinator reserves trusted checking capacity before issuing work. Application limits reduce exposure; they are not a provider-enforced spending cap.</p></div>
